(1063364, 128415, 30251, '<td valign="top">Hey? We''re the wind?</td>', 'Hey? We''re the wind?', '2004-12-15 02:43:48.000000', NULL, 1),
(1063366, 128392, 22479, '<td valign="top">I think you missed an important venue for expressing your perspective on this entry by leaving it untitled. The sky has an unnatural hue and saturation as a result of what I suspect to be an overindulgence of hue/saturation adjustment. If the sky was indeed this color, then I commend you for an excellent capture. The motion blur is excellent in reinforcing the message here and quite appropriate for the challenge theme. Don''t be shy in giving your entries a creative title. Ultimately, you are hurting yourself.</td>', 'I think you missed an important venue for expressing your perspective on this entry by leaving it untitled. The sky has an unnatural hue and saturation as a result of what I suspect to be an overindulgence of hue/saturation adjustment. If the sky was indeed this color, then I commend you for an excellent capture. The motion blur is excellent in reinforcing the message here and quite appropriate for the challenge theme. Don''t be shy in giving your entries a creative title. Ultimately, you are hurting yourself.', '2004-12-15 02:44:32.000000', NULL, 1),
(1063368, 128398, 30251, '<td valign="top">Nice shot, I like the lighting a lot. It''s always nice to see a brder that''s not tacky and accually adds to the image. Well done. I think this should be a medal winner.</td>', 'Nice shot, I like the lighting a lot. It''s always nice to see a brder that''s not tacky and accually adds to the image. Well done. I think this should be a medal winner.', '2004-12-15 02:45:17.000000', NULL, 1),
