(1063473, 128485, 29486, '<td valign="top">Got that right</td>', 'Got that right', '2004-12-15 03:43:33.000000', NULL, 1),
(1063475, 128466, 13749, '<td valign="top">i don''t mind the possible stretch to meet the challenge, but i feel that it is maybe just slightly more contrasty than i like.  interesting choice on dof, and i guess a good choice considering that the rear end probably isn''t farting in the wind ;0</td>', 'i don''t mind the possible stretch to meet the challenge, but i feel that it is maybe just slightly more contrasty than i like.  interesting choice on dof, and i guess a good choice considering that the rear end probably isn''t farting in the wind ;0', '2004-12-15 03:44:38.000000', NULL, 1),
