(1065185, 128429, 25464, '<td valign="top">Soft focus is too distracting and the shot is too busy. 4.</td>', 'Soft focus is too distracting and the shot is too busy. 4.', '2004-12-16 00:22:10.000000', NULL, 1),
(1065186, 128399, 18799, '<td valign="top">Very interesting image.  I''ll be looking forward to the explaination after the challenge.   9</td>', 'Very interesting image.  I''ll be looking forward to the explaination after the challenge.   9', '2004-12-16 00:23:08.000000', NULL, 1),
(1065187, 127757, 18799, '<td valign="top">Beautiful picture, wind aspect is a little weak though</td>', 'Beautiful picture, wind aspect is a little weak though', '2004-12-16 00:23:51.000000', NULL, 1),
(1065190, 128464, 18799, '<td valign="top">It''s a good risk taking image.  It doesn''t really say as much about wind as about movement for me though.   A little overexposed in the background (to be expected to get the movement, I suppose.)   6</td>', 'It''s a good risk taking image.  It doesn''t really say as much about wind as about movement for me though.   A little overexposed in the background (to be expected to get the movement, I suppose.)   6', '2004-12-16 00:27:15.000000', NULL, 1),
(1065191, 127083, 18799, '<td valign="top">Says wind, and meets the challenge.  The interest level created by the choices in composition isn''t very high though.  5</td>', 'Says wind, and meets the challenge.  The interest level created by the choices in composition isn''t very high though.  5', '2004-12-16 00:28:17.000000', NULL, 1),
(1065193, 128484, 18799, '<td valign="top">It''s a nice image, with good exposure and nice colors - one problem.  Nothing here says or shows wind to me.  It it''s really windy, you could have caught it with a little slower shutter.</td>', 'It''s a nice image, with good exposure and nice colors - one problem.  Nothing here says or shows wind to me.  It it''s really windy, you could have caught it with a little slower shutter.', '2004-12-16 00:30:03.000000', NULL, 1),
