(1065195, 128464, 19430, '<td valign="top">Cheaters never win: 1</td>', 'Cheaters never win: 1', '2004-12-16 00:32:17.000000', NULL, 1),
(1065196, 127681, 30457, '<td valign="top">I THOUGHT THE WAY THE AUTHOR FRAMED HIS SUBJECT GAVE THE PHOTO IMPACT. B/W ALSO DOES THE IMAGE JUSTICE. NICE JOB!</td>', 'I THOUGHT THE WAY THE AUTHOR FRAMED HIS SUBJECT GAVE THE PHOTO IMPACT. B/W ALSO DOES THE IMAGE JUSTICE. NICE JOB!', '2004-12-16 00:34:08.000000', NULL, 1),
(1065197, 128409, 22970, '<td valign="top">I think you have done a good job of meeting the wind challenge. I like the concept and your picture has good color, motion, and creativity. 6</td>', 'I think you have done a good job of meeting the wind challenge. I like the concept and your picture has good color, motion, and creativity. 6', '2004-12-16 00:34:34.000000', NULL, 1),
(1065204, 128457, 22970, '<td valign="top">A little dark but a good job of showing wind in your photograph. I dont know if I like the perspective but the colors are good on the dark background.</td>', 'A little dark but a good job of showing wind in your photograph. I dont know if I like the perspective but the colors are good on the dark background.', '2004-12-16 00:37:33.000000', NULL, 1),
(1065206, 128425, 22970, '<td valign="top">You meet the challenge well IMO and with an interesting shot. Good lighting, color, focus, and SS. 6</td>', 'You meet the challenge well IMO and with an interesting shot. Good lighting, color, focus, and SS. 6', '2004-12-16 00:39:46.000000', NULL, 1),
