(1065263, 128131, 28141, '<td valign="top">Sorry, but this is a pretty dull image...not worth adding letters to the theme to make it fit.</td>', 'Sorry, but this is a pretty dull image...not worth adding letters to the theme to make it fit.', '2004-12-16 02:18:41.000000', NULL, 1),
(1065264, 127930, 13749, '<td valign="top">your composition and choice provide a l ot of potential, but unfortunately the amount of lens flare really hurts the image here, as well as the high leve of noise in the sky.</td>', 'your composition and choice provide a l ot of potential, but unfortunately the amount of lens flare really hurts the image here, as well as the high leve of noise in the sky.', '2004-12-16 02:19:21.000000', NULL, 1),
(1065266, 127052, 13749, '<td valign="top">nice title :p.  anyway, GREAT picture - if i could ever capture a moment like this, i''d be happy with my photography for quite awhile.  that being said, i don''t know what else could improve it (other than things that aren''t really in your contorl, such as the structure''s reflection).  nice positioning/dynamic diaganol, and even a shot of the bird''s head as it turns.  10</td>', 'nice title :p.  anyway, GREAT picture - if i could ever capture a moment like this, i''d be happy with my photography for quite awhile.  that being said, i don''t know what else could improve it (other than things that aren''t really in your contorl, such as the structure''s reflection).  nice positioning/dynamic diaganol, and even a shot of the bird''s head as it turns.  10', '2004-12-16 02:21:24.000000', NULL, 1),
(1065267, 128305, 28141, '<td valign="top">too small</td>', 'too small', '2004-12-16 02:24:03.000000', NULL, 1),
