(1065270, 128260, 28141, '<td valign="top">The border is distracting.</td>', 'The border is distracting.', '2004-12-16 02:29:08.000000', NULL, 1),
(1065271, 128244, 28141, '<td valign="top">I would have shown more of the ground silhouette or cropped it out entirely.</td>', 'I would have shown more of the ground silhouette or cropped it out entirely.', '2004-12-16 02:30:11.000000', NULL, 1),
(1065275, 127786, 25623, '<td valign="top">More like Madonna...</td>', 'More like Madonna...', '2004-12-16 02:36:16.000000', NULL, 1),
(1065276, 128299, 22970, '<td valign="top">IMO I believe your photograph meets the challenge. I dont know if the b&amp;w look is the best but I have not seen the colored version so I cant say for sure. Good lighting but low contrast. Overall an average photograph and I wish you well in the challenge.</td>', 'IMO I believe your photograph meets the challenge. I dont know if the b&w look is the best but I have not seen the colored version so I cant say for sure. Good lighting but low contrast. Overall an average photograph and I wish you well in the challenge.', '2004-12-16 02:37:06.000000', NULL, 1),
(1065277, 128161, 28108, '<td valign="top">Very nice picture, I love the tone. I don''t like the slant. 99.9% of the time, it seems inapropriate.</td>', 'Very nice picture, I love the tone. I don''t like the slant. 99.9% of the time, it seems inapropriate.', '2004-12-16 02:38:54.000000', NULL, 1),
