INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1065281, 127472, 26030, '<td valign="top">overall very nice shoot   10<br/>wanderfull background   10<br/>good matching picture with the nature      10<br/> i really enjoy that shoot <br/> <br/>                                                                                  good luck</td>', 'overall very nice shoot   10wanderfull background   10good matching picture with the nature      10 i really enjoy that shoot                                                                                    good luck', '2004-12-16 03:00:40.000000', NULL, 1),
(1065284, 128073, 23300, '<td valign="top">The image itself is quite dramatic. The saturation works well.  I think the bottom flag pole is a little distracting. I know you probably couldn''t do much about that but it draws my eye quite a bit. Also in all honesty I feel that the border detracts from the image quite alot. A think a plain white border would elegantly enhance the image which is already good.  Good Luck.</td>', 'The image itself is quite dramatic. The saturation works well.  I think the bottom flag pole is a little distracting. I know you probably couldn''t do much about that but it draws my eye quite a bit. Also in all honesty I feel that the border detracts from the image quite alot. A think a plain white border would elegantly enhance the image which is already good.  Good Luck.', '2004-12-16 03:26:10.000000', NULL, 1),
(1065286, 127680, 23300, '<td valign="top">I really like the composition and the motion blur. The title adds to the impact of the image also. I feel the image could be enhanced by some level adjustments, increased saturation and perhaps a curves adjustment to give the tones and colours more impact. Basically to make what is already there stand out more. This would also make an interesting black and white image. This is one of the better examples of motion blur. Good Luck.</td>', 'I really like the composition and the motion blur. The title adds to the impact of the image also. I feel the image could be enhanced by some level adjustments, increased saturation and perhaps a curves adjustment to give the tones and colours more impact. Basically to make what is already there stand out more. This would also make an interesting black and white image. This is one of the better examples of motion blur. Good Luck.', '2004-12-16 03:29:38.000000', NULL, 1),
(1065287, 126934, 23300, '<td valign="top">Its a lovely image however it does not represent the concept of wind to me all that well. I''m trying to make a connection between the shape of the clouds and the idea of wind but its not that strong. Its  a beautiful image all the same.</td>', 'Its a lovely image however it does not represent the concept of wind to me all that well. I''m trying to make a connection between the shape of the clouds and the idea of wind but its not that strong. Its  a beautiful image all the same.', '2004-12-16 03:31:25.000000', NULL, 1),
(1065288, 126934, 16636, '<td valign="top">not sure about the wind, but a very nice image anyway</td>', 'not sure about the wind, but a very nice image anyway', '2004-12-16 03:33:48.000000', NULL, 1),
(1065289, 127986, 23300, '<td valign="top">I love the colours and tones of this image. The composition is well balanced in a random way.  The textures and colours make it almost touchable. The blur, if thats what it is, works well to represent the challenge theme. Its a beautiful and balanced image with a touch of drama.</td>', 'I love the colours and tones of this image. The composition is well balanced in a random way.  The textures and colours make it almost touchable. The blur, if thats what it is, works well to represent the challenge theme. Its a beautiful and balanced image with a touch of drama.', '2004-12-16 03:34:40.000000', NULL, 1),
