(1066577, 128351, 29269, '<td valign="top">This might be too tight of a crop - seeing more of the surroundings (preferably empty sky) would better convey the sense of free flying. As is - 6.</td>', 'This might be too tight of a crop - seeing more of the surroundings (preferably empty sky) would better convey the sense of free flying. As is - 6.', '2004-12-16 23:28:17.000000', NULL, 1),
(1066580, 128415, 29269, '<td valign="top">Don''t see much wind here... The image also has light spots that draw too much attention. 3.</td>', 'Don''t see much wind here... The image also has light spots that draw too much attention. 3.', '2004-12-16 23:30:41.000000', NULL, 1),
(1066585, 127757, 22734, '<td valign="top">A very appropiate entry which many DPC members will dismiss because they never had reason to appreciate the Fan. Westerners give little weight to the physics inherest in a fan to create wind. Expressions of fanning the flames have been around, but in this age of air conditioning the past is easily overlooked. <br/> <br/>Well, my only concern is that the part of the face that shows should have received the ultimate attention to capture the skin tones at the expense of the fan. That is the fan has enough color that you can favor the skin tones and still have enough impressive color on the fan.<br/> <br/>The composition is just great and really above average. You do have a flair and I suggest you give yourself enough time to tweak your images. Had the skin tones been up to par I would have given the image an 8. As is you get a 7. I had you in my holding place of 5 and your are being bumped 2 notches.</td>', 'A very appropiate entry which many DPC members will dismiss because they never had reason to appreciate the Fan. Westerners give little weight to the physics inherest in a fan to create wind. Expressions of fanning the flames have been around, but in this age of air conditioning the past is easily overlooked.  Well, my only concern is that the part of the face that shows should have received the ultimate attention to capture the skin tones at the expense of the fan. That is the fan has enough color that you can favor the skin tones and still have enough impressive color on the fan. The composition is just great and really above average. You do have a flair and I suggest you give yourself enough time to tweak your images. Had the skin tones been up to par I would have given the image an 8. As is you get a 7. I had you in my holding place of 5 and your are being bumped 2 notches.', '2004-12-16 23:34:56.000000', NULL, 1),
(1066594, 127785, 29269, '<td valign="top">I like this one! nice, crisp image of the sail, perfect for the challenge. The only thing I could come up with as a constructive criticism is:<br/>- tighter crop - removing the wave at the bottom would draw more attention (all the attention) to the surfer.<br/>- playing with levels and hue to make the gray sky color livelier.<br/>As is - 9.</td>', 'I like this one! nice, crisp image of the sail, perfect for the challenge. The only thing I could come up with as a constructive criticism is:- tighter crop - removing the wave at the bottom would draw more attention (all the attention) to the surfer.- playing with levels and hue to make the gray sky color livelier.As is - 9.', '2004-12-16 23:47:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1066603, 127565, 25464, '<td valign="top">Excellent photo. Very well composed interesting.  Maybe a little dark on the face, but I think that is mostly attributed to the glasses.  Bumping up to 8.</td>', 'Excellent photo. Very well composed interesting.  Maybe a little dark on the face, but I think that is mostly attributed to the glasses.  Bumping up to 8.', '2004-12-17 00:00:07.000000', NULL, 1),
(1066605, 127895, 25464, '<td valign="top">This is a nicely composed shot, but the color looks off to me.  The brick color appears flat, and the boy appears to have blue-green shadows on his hand, chin, and lower lip.  Meets the challenge well. 6.</td>', 'This is a nicely composed shot, but the color looks off to me.  The brick color appears flat, and the boy appears to have blue-green shadows on his hand, chin, and lower lip.  Meets the challenge well. 6.', '2004-12-17 00:02:21.000000', NULL, 1),
(1066607, 127342, 25464, '<td valign="top">Meets the challenge well, nicely composed, but no real wow for me.  I think the mostly cloudy sky is lessening the impact of this shot quite a bit. 6.</td>', 'Meets the challenge well, nicely composed, but no real wow for me.  I think the mostly cloudy sky is lessening the impact of this shot quite a bit. 6.', '2004-12-17 00:03:46.000000', NULL, 1),
(1066610, 127763, 25464, '<td valign="top">predictable, but well executed shot.  I think the person in the shot and table, etc are distracting rather than enhancing this image. 7.</td>', 'predictable, but well executed shot.  I think the person in the shot and table, etc are distracting rather than enhancing this image. 7.', '2004-12-17 00:05:41.000000', NULL, 1),
(1066612, 128410, 25464, '<td valign="top">Framing is interesting.  Nice light and color. 7.</td>', 'Framing is interesting.  Nice light and color. 7.', '2004-12-17 00:07:15.000000', NULL, 1),
(1066613, 128234, 25464, '<td valign="top">This is a good idea for the challenge, blur is appropriate.  The rest of the image is sharp, but this angle doesnt really do anything for me. 7.</td>', 'This is a good idea for the challenge, blur is appropriate.  The rest of the image is sharp, but this angle doesnt really do anything for me. 7.', '2004-12-17 00:08:58.000000', NULL, 1),
(1066618, 127645, 25464, '<td valign="top">I think this has great potential, but would have been better taken as an offset landscape shot.  It seems jammed in the frame.  Too crowded.  Nice focus and color.  Interesting subject.  7.</td>', 'I think this has great potential, but would have been better taken as an offset landscape shot.  It seems jammed in the frame.  Too crowded.  Nice focus and color.  Interesting subject.  7.', '2004-12-17 00:11:12.000000', NULL, 1),
(1066623, 127650, 25464, '<td valign="top">The completely cloudy sky and the blade of the windmill leaving the frame at the top are distractions, but pretty good. 6.</td>', 'The completely cloudy sky and the blade of the windmill leaving the frame at the top are distractions, but pretty good. 6.', '2004-12-17 00:13:03.000000', NULL, 1),
(1066625, 127606, 25464, '<td valign="top">This is emotional, meets the challenge, has great composition and focus (with the exception of the over abundance of hair covering the face.)  The womans posture speaks volumes. Bumping up to 9.</td>', 'This is emotional, meets the challenge, has great composition and focus (with the exception of the over abundance of hair covering the face.)  The womans posture speaks volumes. Bumping up to 9.', '2004-12-17 00:15:18.000000', NULL, 1),
(1066638, 126980, 25464, '<td valign="top">This is an interesting and emotive shot that is damaged by the title.  The title leads one to believe that you are attempting to portray someone enjoying wind in their hair (like a cool breeze on a warm beach).  This photo gives off, very effectively, a sad or lonely feeling.  The focus is a wee bit soft which I think is appropriate in this case.  The tones are very nice, maybe a bit blown out in the background, but again, appropriate for the sad, lonely feeling.  The pose is great.  I think it is a great shot that could have scored even higher with the appropriate title. 8.</td>', 'This is an interesting and emotive shot that is damaged by the title.  The title leads one to believe that you are attempting to portray someone enjoying wind in their hair (like a cool breeze on a warm beach).  This photo gives off, very effectively, a sad or lonely feeling.  The focus is a wee bit soft which I think is appropriate in this case.  The tones are very nice, maybe a bit blown out in the background, but again, appropriate for the sad, lonely feeling.  The pose is great.  I think it is a great shot that could have scored even higher with the appropriate title. 8.', '2004-12-17 00:21:52.000000', NULL, 1),
(1066663, 128174, 16241, '<td valign="top">very athletic :)</td>', 'very athletic :)', '2004-12-17 01:21:06.000000', NULL, 1),
(1066664, 127490, 16241, '<td valign="top">cutest thing!</td>', 'cutest thing!', '2004-12-17 01:22:40.000000', NULL, 1),
(1066665, 127911, 16241, '<td valign="top">this would have been more effective without the sunglasses i think?<br/></td>', 'this would have been more effective without the sunglasses i think?', '2004-12-17 01:23:53.000000', NULL, 1),
(1066668, 128487, 16241, '<td valign="top">thats cool</td>', 'thats cool', '2004-12-17 01:24:40.000000', NULL, 1),
