(1068787, 128480, 17047, '<td valign="top">Great subject matter but would have been so much better with more tonal seperation between the horn and the background. The bell of it just blends in a bit too much.</td>', 'Great subject matter but would have been so much better with more tonal seperation between the horn and the background. The bell of it just blends in a bit too much.', '2004-12-19 08:56:26.000000', NULL, 1),
(1068829, 128076, 17047, '<td valign="top">LMAO! I gave you an extra point just for the concept :D</td>', 'LMAO! I gave you an extra point just for the concept :D', '2004-12-19 10:05:50.000000', NULL, 1),
(1068854, 128215, 18374, '<td valign="top">This image looks like it had a heavy editing hand- like the contrast and birghtness were cranked up too much.  I think this shot could be greatly improved by shooting with a different background.  The blown out sky and multiple telephone lines cris-crossing the image greatly detract from the photo.  A more shallow depth of field might also help, but you might not be able to achieve it and still get the motion blur in the wings (depending on your equipment).  Using your flash for some fill lighting  might help expose the bird properly without making the sky as overexposed.  These are just some techniques that in my opinion might help improve this image.</td>', 'This image looks like it had a heavy editing hand- like the contrast and birghtness were cranked up too much.  I think this shot could be greatly improved by shooting with a different background.  The blown out sky and multiple telephone lines cris-crossing the image greatly detract from the photo.  A more shallow depth of field might also help, but you might not be able to achieve it and still get the motion blur in the wings (depending on your equipment).  Using your flash for some fill lighting  might help expose the bird properly without making the sky as overexposed.  These are just some techniques that in my opinion might help improve this image.', '2004-12-19 10:37:43.000000', NULL, 1),
(1068856, 128033, 18374, '<td valign="top">This is an interesting image, but the white balance looks off to me.  If this shot was lit with tungsten lights, try setting the white balance to tungsten and take a look at the results.  It should render the pages white instead of the pale yellow they are now.  If the yellow was intentional, then ignore my comment!</td>', 'This is an interesting image, but the white balance looks off to me.  If this shot was lit with tungsten lights, try setting the white balance to tungsten and take a look at the results.  It should render the pages white instead of the pale yellow they are now.  If the yellow was intentional, then ignore my comment!', '2004-12-19 10:42:38.000000', NULL, 1),
(1068867, 127757, 18374, '<td valign="top">Very interesting composition.  In my opinion, this shot would be strengthened by some more dynamic lighting.  Right now the lighting is kind of flat and pale- like it was lit with an overhead flourescent light and a weak flash for front lighting.  Some ideas that I might try to add some lighting interest to the shot are adding a warm side light aimed at the model but avoiding the fan to increase the dynamic range difference between her face and the fan.  Alternatively adding a backlight aimed at the fan might give the same result but in a different way.  <br/>Nice job with the framing of this shot.  I think it is a very strong composition.  Good luck.</td>', 'Very interesting composition.  In my opinion, this shot would be strengthened by some more dynamic lighting.  Right now the lighting is kind of flat and pale- like it was lit with an overhead flourescent light and a weak flash for front lighting.  Some ideas that I might try to add some lighting interest to the shot are adding a warm side light aimed at the model but avoiding the fan to increase the dynamic range difference between her face and the fan.  Alternatively adding a backlight aimed at the fan might give the same result but in a different way.  Nice job with the framing of this shot.  I think it is a very strong composition.  Good luck.', '2004-12-19 10:57:16.000000', NULL, 1),
(1068879, 127766, 18374, '<td valign="top">Very cool!  This looks like an Australian class skiff race.  Very good light, and I like the background.  With the crew hiked out that you really get the impression of strong wind.</td>', 'Very cool!  This looks like an Australian class skiff race.  Very good light, and I like the background.  With the crew hiked out that you really get the impression of strong wind.', '2004-12-19 11:20:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1068884, 128189, 18374, '<td valign="top">I''m not buying the wind aspect of this photo, but it is a very nice shot.  The color and background framing the image are very nice.  I like the low angle from which this was taken.</td>', 'I''m not buying the wind aspect of this photo, but it is a very nice shot.  The color and background framing the image are very nice.  I like the low angle from which this was taken.', '2004-12-19 11:25:54.000000', NULL, 1),
