(1068951, 128431, 14438, '<td valign="top">Vertical smoke = no wind. <br/>Nice colors<br/>&lt;4&gt;<br/></td>', 'Vertical smoke = no wind. Nice colors<4>', '2004-12-19 13:26:24.000000', NULL, 1),
