(1071924, 127297, 30712, '<td valign="top">An interesting mix of shapes and tones.</td>', 'An interesting mix of shapes and tones.', '2004-12-21 11:17:16.000000', NULL, 1),
(1071929, 128391, 30712, '<td valign="top">A good idea but the result doesn''t hold my attention sufficiently.  A more interesting background might have made a bolder statement.</td>', 'A good idea but the result doesn''t hold my attention sufficiently.  A more interesting background might have made a bolder statement.', '2004-12-21 11:18:30.000000', NULL, 1),
(1071935, 128473, 30712, '<td valign="top">A great scene.  I''d lke to have seen the boats leaning more to have made the wind more of a  feature for this competition.</td>', 'A great scene.  I''d lke to have seen the boats leaning more to have made the wind more of a  feature for this competition.', '2004-12-21 11:19:39.000000', NULL, 1),
