(1071969, 128350, 30712, '<td valign="top">This works!</td>', 'This works!', '2004-12-21 11:35:55.000000', NULL, 1),
(1071971, 128370, 30712, '<td valign="top">Not windy enough for me but a lovely picture.</td>', 'Not windy enough for me but a lovely picture.', '2004-12-21 11:36:35.000000', NULL, 1),
(1071972, 127608, 30712, '<td valign="top">Delicate.</td>', 'Delicate.', '2004-12-21 11:36:53.000000', NULL, 1),
