(1072035, 127645, 29148, '<td valign="top">Good shot, would have scored it higher if I could see some indication of wind. 7</td>', 'Good shot, would have scored it higher if I could see some indication of wind. 7', '2004-12-21 12:44:57.000000', NULL, 1),
(1072040, 128234, 29148, '<td valign="top">The blur really makes this look like the wind. Good job, 7</td>', 'The blur really makes this look like the wind. Good job, 7', '2004-12-21 12:45:53.000000', NULL, 1),
(1072041, 128338, 29148, '<td valign="top">I would say those trees have seen some wind. a 7</td>', 'I would say those trees have seen some wind. a 7', '2004-12-21 12:46:35.000000', NULL, 1),
