(1072047, 128392, 29148, '<td valign="top">Very similar to mine, great minds run in the same track. Looks like wind to me. A 7</td>', 'Very similar to mine, great minds run in the same track. Looks like wind to me. A 7', '2004-12-21 12:49:03.000000', NULL, 1),
