(1072089, 127921, 27562, '<td valign="top">Too bad the mast was cut off in an otherwise exceelent image.  Good Work.</td>', 'Too bad the mast was cut off in an otherwise exceelent image.  Good Work.', '2004-12-21 13:20:08.000000', NULL, 1),
(1072094, 128147, 27562, '<td valign="top">Really weird color cast, but in a strange way it works.  Good Work.</td>', 'Really weird color cast, but in a strange way it works.  Good Work.', '2004-12-21 13:22:39.000000', NULL, 1),
