(1072098, 127968, 30354, '<td valign="top">i love the colors</td>', 'i love the colors', '2004-12-21 13:25:38.000000', NULL, 1),
(1072182, 127977, 29477, '<td valign="top">Excellent DOF and composition.  Simple yet very clearly demonstrates the challange.  Nice job.</td>', 'Excellent DOF and composition.  Simple yet very clearly demonstrates the challange.  Nice job.', '2004-12-21 14:33:18.000000', NULL, 1),
(1072197, 127052, 29295, '<td valign="top">The way you captured the majestic look of this bird and the blue colour of it is amazing. The colours are so vivid. I can almost hear it wooshing by.</td>', 'The way you captured the majestic look of this bird and the blue colour of it is amazing. The colours are so vivid. I can almost hear it wooshing by.', '2004-12-21 14:43:09.000000', NULL, 1),
